import "fmt"

type Allocator struct {
	next     uint64
	reserved map[string]uint64
}

func (a *Allocator) Reserve(intent string) uint64 {
	if nonce, ok := a.reserved[intent]; ok {
		return nonce
	}
	nonce := a.next
	a.next++
	a.reserved[intent] = nonce
	return nonce
}
func main() {
	// Single-owner model: the durable multi-process implementation is separate.
	a := Allocator{next: 42, reserved: map[string]uint64{}}
	fmt.Println(a.Reserve("invoice-7"), a.Reserve("invoice-7"), a.Reserve("invoice-8")) // 42 42 43
}

