	chain := []Block{{Height: 10, Hash: "A10", Parent: "A9"}}
	chain, _ = appendBlock(chain, Block{Height: 11, Hash: "A11", Parent: "A10"})
	_, err := appendBlock(chain, Block{Height: 11, Hash: "B11", Parent: "A10"})
	fmt.Println(err) // replacement is not silently appended
}

package main

import (
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"fmt"
)

type Block struct {
	Height uint64
	Prev   [32]byte
	Data   string
}

// encode is the canonical byte form: fixed-width fields first, then a
// length-prefixed payload, so two different blocks never share bytes.
func encode(b Block) []byte {
	buf := binary.BigEndian.AppendUint64(nil, b.Height)
	buf = append(buf, b.Prev[:]...)
	buf = binary.BigEndian.AppendUint32(buf, uint32(len(b.Data)))
	return append(buf, b.Data...)
}

func hash(b Block) [32]byte { return sha256.Sum256(encode(b)) }

func build(payloads ...string) []Block {
	var chain []Block
	var prev [32]byte // genesis points at the all-zero hash
	for i, p := range payloads {
		b := Block{Height: uint64(i), Prev: prev, Data: p}
		chain = append(chain, b)
		prev = hash(b)
	}
	return chain
}

// firstBrokenLink returns the height of the first block that does not commit
// to its predecessor, or -1 when every link holds.
func firstBrokenLink(chain []Block) int {
	for i := 1; i < len(chain); i++ {
		if chain[i].Height != chain[i-1].Height+1 || chain[i].Prev != hash(chain[i-1]) {
			return i
		}
	}
	return -1
}

func short(h [32]byte) string { return hex.EncodeToString(h[:4]) }

func main() {
	chain := build("genesis", "alice->bob:5", "bob->carol:2", "carol->dave:1")
	trustedTip := hash(chain[len(chain)-1])
	fmt.Println("links ok:", firstBrokenLink(chain) == -1, "tip:", short(trustedTip))

	chain[1].Data = "alice->bob:500"
	fmt.Println("after edit, first broken link at height", firstBrokenLink(chain))

	for i := 2; i < len(chain); i++ {
		chain[i].Prev = hash(chain[i-1])
	}
	tip := hash(chain[len(chain)-1])
	fmt.Println("relinked:", firstBrokenLink(chain) == -1, "tip:", short(tip))
	fmt.Println("matches trusted tip:", tip == trustedTip)
}

