package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
)

type Hash = [32]byte

// Domain separation: a leaf hash can never be confused with an interior node.
func leafHash(data []byte) Hash { return sha256.Sum256(append([]byte{0x00}, data...)) }

func nodeHash(l, r Hash) Hash {
	return sha256.Sum256(append(append([]byte{0x01}, l[:]...), r[:]...))
}

// levels builds the tree bottom-up. A lone last node is promoted unchanged,
// never paired with a copy of itself.
func levels(leaves [][]byte) [][]Hash {
	level := make([]Hash, len(leaves))
	for i, d := range leaves {
		level[i] = leafHash(d)
	}
	tree := [][]Hash{level}
	for len(level) > 1 {
		var next []Hash
		for i := 0; i < len(level); i += 2 {
			if i+1 < len(level) {
				next = append(next, nodeHash(level[i], level[i+1]))
			} else {
				next = append(next, level[i])
			}
		}
		tree = append(tree, next)
		level = next
	}
	return tree
}

func root(leaves [][]byte) Hash {
	t := levels(leaves)
	return t[len(t)-1][0]
}

func prove(leaves [][]byte, index int) []Hash {
	var proof []Hash
	for _, level := range levels(leaves) {
		sibling := index ^ 1
		if sibling < len(level) {
			proof = append(proof, level[sibling])
		}
		index /= 2
	}
	return proof
}

// verify recomputes the root from the leaf, its index and the tree size, so
// left/right order comes from the claimed position, not from the proof.
func verify(leaf []byte, index, size int, proof []Hash, want Hash) bool {
	if index < 0 || index >= size {
		return false
	}
	h := leafHash(leaf)
	for n := size; n > 1; n = (n + 1) / 2 {
		if index%2 == 1 || index+1 < n {
			if len(proof) == 0 {
				return false
			}
			if index%2 == 1 {
				h = nodeHash(proof[0], h)
			} else {
				h = nodeHash(h, proof[0])
			}
			proof = proof[1:]
		}
		index /= 2
	}
	return len(proof) == 0 && h == want
}

// naiveRoot is the classic shape: no prefixes, odd levels duplicate the last hash.
func naiveRoot(leaves [][]byte) Hash {
	level := make([]Hash, len(leaves))
	for i, d := range leaves {
		level[i] = sha256.Sum256(d)
	}
	for len(level) > 1 {
		if len(level)%2 == 1 {
			level = append(level, level[len(level)-1])
		}
		var next []Hash
		for i := 0; i < len(level); i += 2 {
			next = append(next, sha256.Sum256(append(level[i][:], level[i+1][:]...)))
		}
		level = next
	}
	return level[0]
}

func split(s ...string) [][]byte {
	out := make([][]byte, len(s))
	for i, v := range s {
		out[i] = []byte(v)
	}
	return out
}

func main() {
	txs := split("tx-a", "tx-b", "tx-c", "tx-d", "tx-e")
	r := root(txs)
	fmt.Println("root:", hex.EncodeToString(r[:4]), "leaves:", len(txs))

	proof := prove(txs, 2)
	fmt.Println("proof for leaf 2:", len(proof), "hashes, valid:", verify(txs[2], 2, len(txs), proof, r))
	fmt.Println("tampered leaf valid:", verify([]byte("tx-x"), 2, len(txs), proof, r))
	fmt.Println("wrong index valid:", verify(txs[2], 3, len(txs), proof, r))

	three, four := split("a", "b", "c"), split("a", "b", "c", "c")
	ha, hb := sha256.Sum256([]byte("a")), sha256.Sum256([]byte("b"))
	hc, hd := sha256.Sum256([]byte("c")), sha256.Sum256([]byte("d"))
	honest := split("a", "b", "c", "d")
	forged := [][]byte{append(ha[:], hb[:]...), append(hc[:], hd[:]...)}

	fmt.Println("naive [a b c] == [a b c c]:", naiveRoot(three) == naiveRoot(four))
	fmt.Println("naive 4 leaves == 2 forged leaves:", naiveRoot(honest) == naiveRoot(forged))
	fmt.Println("separated [a b c] == [a b c c]:", root(three) == root(four))
	fmt.Println("separated 4 leaves == 2 forged leaves:", root(honest) == root(forged))
}

package main

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"strings"

	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/crypto"
)

var (
	errFormat   = errors.New("want 0x followed by 40 hex digits")
	errChecksum = errors.New("mixed-case input fails the EIP-55 checksum")
	errZero     = errors.New("zero address is not a valid destination")
)

// eip55 re-implements the checksum to show the rule: uppercase a letter when
// the matching nibble of keccak256(lowercase hex) is 8 or more.
func eip55(a common.Address) string {
	lower := hex.EncodeToString(a[:])
	h := crypto.Keccak256([]byte(lower))
	out := []byte(lower)
	for i, c := range out {
		nibble := h[i/2] >> 4
		if i%2 == 1 {
			nibble = h[i/2] & 0x0f
		}
		if c >= 'a' && nibble >= 8 {
			out[i] = c - 32
		}
	}
	return "0x" + string(out)
}

func parseAddress(s string) (common.Address, error) {
	if len(s) != 42 || !strings.HasPrefix(s, "0x") || !common.IsHexAddress(s) {
		return common.Address{}, errFormat
	}
	a := common.HexToAddress(s)
	body := s[2:]
	mixed := body != strings.ToLower(body) && body != strings.ToUpper(body)
	if mixed && s != a.Hex() {
		return common.Address{}, errChecksum
	}
	if a == (common.Address{}) {
		return common.Address{}, errZero
	}
	return a, nil
}

func main() {
	// TEST KEY ONLY: fixed bytes, never funded.
	key, _ := crypto.ToECDSA(bytes.Repeat([]byte{1}, 32))
	pub := crypto.FromECDSAPub(&key.PublicKey) // 0x04 || X || Y, 65 bytes
	derived := common.BytesToAddress(crypto.Keccak256(pub[1:])[12:])
	fmt.Println("pubkey bytes:", len(pub), "derived == PubkeyToAddress:", derived == crypto.PubkeyToAddress(key.PublicKey))
	fmt.Println("lowercase:", strings.ToLower(derived.Hex()))
	fmt.Println("EIP-55:   ", derived.Hex(), "manual matches:", eip55(derived) == derived.Hex())

	good := derived.Hex()
	lower := strings.ToLower(good)
	flipped := good[:9] + strings.ToLower(good[9:10]) + good[10:] // E written as e
	typo := lower[:41] + "0"                                      // last digit mistyped, all lowercase
	cases := []struct{ label, in string }{
		{"checksummed", good}, {"lowercase", lower}, {"one case flipped", flipped},
		{"lowercase typo", typo}, {"too short", "0x1a642f"}, {"zero", "0x" + strings.Repeat("0", 40)},
	}
	for _, c := range cases {
		a, err := parseAddress(c.in)
		if err != nil {
			fmt.Printf("%-16s reject: %v\n", c.label, err)
			continue
		}
		fmt.Printf("%-16s accept, signer: %v\n", c.label, a == derived)
	}

	m, _ := common.NewMixedcaseAddressFromString(strings.ToLower(good))
	fmt.Println("MixedcaseAddress.ValidChecksum(lowercase):", m.ValidChecksum())

	var req struct {
		To common.Address `json:"to"`
	}
	err := json.Unmarshal([]byte(`{"amount":"5"}`), &req)
	fmt.Println("missing field decodes to zero address:", err == nil && req.To == common.Address{})
	fmt.Println("HexToAddress(\"0xzz\") is zero:", common.HexToAddress("0xzz") == common.Address{})
}

package main

import (
	"errors"
	"fmt"
)

// ---- UTXO model: state is the set of unspent outputs ----

type OutPoint struct {
	Tx    string
	Index int
}

type Output struct {
	Owner  string
	Amount uint64
}

type Tx struct {
	ID      string
	Owner   string // stands in for a signature check on every input
	Inputs  []OutPoint
	Outputs []Output
}

type UTXOSet map[OutPoint]Output

func (u UTXOSet) Apply(tx Tx) error {
	var in, out uint64
	seen := map[OutPoint]bool{}
	for _, op := range tx.Inputs {
		if seen[op] {
			return fmt.Errorf("input %s:%d used twice", op.Tx, op.Index)
		}
		seen[op] = true
		prev, ok := u[op]
		if !ok {
			return fmt.Errorf("input %s:%d is spent or unknown", op.Tx, op.Index)
		}
		if prev.Owner != tx.Owner {
			return fmt.Errorf("input %s:%d not owned by %s", op.Tx, op.Index, tx.Owner)
		}
		in += prev.Amount
	}
	for _, o := range tx.Outputs {
		out += o.Amount
	}
	if out > in {
		return fmt.Errorf("outputs %d exceed inputs %d", out, in)
	}
	// Validate everything first, then mutate: a rejected tx leaves no trace.
	for _, op := range tx.Inputs {
		delete(u, op)
	}
	for i, o := range tx.Outputs {
		u[OutPoint{tx.ID, i}] = o
	}
	return nil
}

// Balance is derived: nobody stores it, an indexer sums unspent outputs.
func (u UTXOSet) Balance(owner string) uint64 {
	var sum uint64
	for _, o := range u {
		if o.Owner == owner {
			sum += o.Amount
		}
	}
	return sum
}

// ---- Account model: state is a balance and a nonce per account ----

type Account struct{ Balance, Nonce uint64 }

type Transfer struct {
	From, To      string
	Amount, Nonce uint64
}

type Ledger map[string]*Account

var errUnknown = errors.New("unknown sender")

func (l Ledger) Apply(t Transfer) error {
	from := l[t.From]
	if from == nil {
		return errUnknown
	}
	if t.Nonce != from.Nonce {
		return fmt.Errorf("nonce %d rejected, next is %d", t.Nonce, from.Nonce)
	}
	if from.Balance < t.Amount {
		return fmt.Errorf("balance %d < %d", from.Balance, t.Amount)
	}
	if l[t.To] == nil {
		l[t.To] = &Account{}
	}
	from.Balance -= t.Amount
	l[t.To].Balance += t.Amount
	from.Nonce++
	return nil
}

func report(label string, err error) {
	if err != nil {
		fmt.Printf("%-28s rejected: %v\n", label, err)
		return
	}
	fmt.Printf("%-28s ok\n", label)
}

func main() {
	utxo := UTXOSet{{"genesis", 0}: {"alice", 50}}
	pay := Tx{ID: "t1", Owner: "alice", Inputs: []OutPoint{{"genesis", 0}},
		Outputs: []Output{{"bob", 30}, {"alice", 19}}} // 1 unit left over is the fee
	report("utxo: alice pays bob 30", utxo.Apply(pay))
	report("utxo: spend genesis:0 again", utxo.Apply(Tx{ID: "t2", Owner: "alice",
		Inputs: []OutPoint{{"genesis", 0}}, Outputs: []Output{{"carol", 50}}}))
	report("utxo: same input twice", utxo.Apply(Tx{ID: "t3", Owner: "alice",
		Inputs: []OutPoint{{"t1", 1}, {"t1", 1}}, Outputs: []Output{{"carol", 38}}}))
	fmt.Println("utxo balances: alice", utxo.Balance("alice"), "bob", utxo.Balance("bob"), "outputs", len(utxo))

	genesis := func() Ledger { return Ledger{"alice": {Balance: 50}} }
	ledger := genesis()
	var history []Transfer
	for _, step := range []struct {
		label string
		t     Transfer
	}{
		{"account: alice pays bob 30", Transfer{"alice", "bob", 30, 0}},
		{"account: replay nonce 0", Transfer{"alice", "bob", 30, 0}},
		{"account: alice pays carol 30", Transfer{"alice", "carol", 30, 1}},
	} {
		err := ledger.Apply(step.t)
		if err == nil {
			history = append(history, step.t)
		}
		report(step.label, err)
	}
	fmt.Println("account balances: alice", ledger["alice"].Balance, "bob", ledger["bob"].Balance, "alice nonce", ledger["alice"].Nonce)

	rebuilt := genesis()
	for _, t := range history {
		if err := rebuilt.Apply(t); err != nil {
			panic(err) // accepted history must always replay
		}
	}
	fmt.Println("rebuilt from history matches:", *rebuilt["alice"] == *ledger["alice"] && *rebuilt["bob"] == *ledger["bob"])
}

package main

import (
	"bytes"
	"encoding/hex"
	"fmt"
	"io"
	"math/big"

	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/rlp"
)

type Transfer struct {
	Nonce uint64
	To    common.Address
	Value *big.Int
	Data  []byte
}

func enc(v any) string {
	b, err := rlp.EncodeToBytes(v)
	if err != nil {
		return "error: " + err.Error()
	}
	return hex.EncodeToString(b)
}

func main() {
	// Vectors from the RLP specification.
	fmt.Println("0:", enc(uint64(0)), "15:", enc(uint64(15)), "1024:", enc(uint64(1024)))
	fmt.Println("dog:", enc("dog"), "[cat dog]:", enc([]string{"cat", "dog"}), "[]:", enc([]uint64{}))
	fmt.Println("negative big.Int:", enc(big.NewInt(-1)))

	t := Transfer{Nonce: 7, To: common.HexToAddress("0x00000000000000000000000000000000000000aa"), Value: big.NewInt(1000)}
	raw, _ := rlp.EncodeToBytes(t)
	fmt.Println("transfer:", len(raw), "bytes", hex.EncodeToString(raw[:4])+"...")
	var back Transfer
	err := rlp.DecodeBytes(raw, &back)
	again, _ := rlp.EncodeToBytes(back)
	fmt.Println("round trip:", err == nil && bytes.Equal(raw, again))

	// Each input below decodes to 5 or 15 in a lax decoder; rlp rejects them.
	for _, in := range []string{"8105", "820005", "b80105", "0f0f", "bbffffffff"} {
		b, _ := hex.DecodeString(in)
		var n uint64
		fmt.Printf("%-10s %v\n", in, rlp.DecodeBytes(b, &n))
	}

	// A stream from the network has no length; cap it explicitly.
	big100 := append([]byte{0xb8, 100}, make([]byte, 100)...)
	var payload []byte
	s := rlp.NewStream(io.MultiReader(bytes.NewReader(big100)), 64)
	fmt.Println("stream limit 64:", s.Decode(&payload))
}

package main

import (
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
