type Header struct {
	Parent [32]byte
	Height uint64
	Data   [32]byte // commitment to the block body, e.g. a Merkle root
	Bits   uint     // difficulty: the target is 2^(256-Bits)
	Nonce  uint64
}

func (h Header) Hash() [32]byte {
	buf := append([]byte(nil), h.Parent[:]...)
	buf = binary.BigEndian.AppendUint64(buf, h.Height)
	buf = append(buf, h.Data[:]...)
	buf = binary.BigEndian.AppendUint64(buf, uint64(h.Bits))
	buf = binary.BigEndian.AppendUint64(buf, h.Nonce)
	return sha256.Sum256(buf)
}

func target(bits uint) *big.Int { return new(big.Int).Lsh(big.NewInt(1), 256-bits) }

// Valid costs one hash, whatever the difficulty.
func Valid(h Header) bool {
	sum := h.Hash()
	return new(big.Int).SetBytes(sum[:]).Cmp(target(h.Bits)) < 0
}

// Mine is the expensive side: about 2^Bits attempts on average.
func Mine(h Header) (Header, uint64) {
	for attempts := uint64(1); ; attempts++ {
		if Valid(h) {
			return h, attempts
		}
		h.Nonce++
	}
}

// Work is the expected number of hashes a header represents: 2^256 / (target+1).
func Work(bits uint) *big.Int {
	t := target(bits)
	return new(big.Int).Div(new(big.Int).Lsh(big.NewInt(1), 256), t.Add(t, big.NewInt(1)))
}

// Retarget scales the target by actual/expected time, clamped to a factor of 4.
func Retarget(old *big.Int, actual, expected int64) *big.Int {
	actual = max(expected/4, min(actual, expected*4))
	t := new(big.Int).Mul(old, big.NewInt(actual))
	return t.Div(t, big.NewInt(expected))
}

func main() {
	body := sha256.Sum256([]byte("toy block body"))
	var last Header
	for _, bits := range []uint{8, 12, 16} {
		h, attempts := Mine(Header{Height: 1, Data: body, Bits: bits})
		sum := h.Hash()
		fmt.Printf("bits %2d: nonce %6d after %6d attempts, hash %s..., work %d\n",
			bits, h.Nonce, attempts, hex.EncodeToString(sum[:3]), Work(bits))
		last = h
	}

	fmt.Println("verify mined header:", Valid(last))
	last.Data[0] ^= 1 // change one bit of the body commitment
	fmt.Println("verify after edit:", Valid(last))

	// Ten blocks were expected to take 6000 s (fixed numbers, not a clock).
	old := target(16)
	for _, actual := range []int64{6000, 3000, 100} {
		next := Retarget(old, actual, 6000)
		fmt.Printf("span %4ds: new target = old * %s\n", actual, new(big.Rat).SetFrac(next, old).RatString())
	}
}

package main

import (
	"fmt"
	"slices"
)

type Block struct {
	ID, Parent string
	Height     uint64
	Work       uint64   // expected hashes for this block, from its target
	Deposits   []string // transactions the indexer cares about
}

type Node struct {
	blocks map[string]Block
	total  map[string]uint64 // cumulative work from genesis
	head   string
}

func NewNode(genesis Block) *Node {
	return &Node{blocks: map[string]Block{genesis.ID: genesis}, total: map[string]uint64{genesis.ID: 0}, head: genesis.ID}
}

// Add stores a block and applies the fork-choice rule: the tip with the most
// cumulative work wins; on a tie the block seen first stays head.
func (n *Node) Add(b Block) (ancestor string, undo, apply []string, err error) {
	parent, ok := n.blocks[b.Parent]
	if !ok || b.Height != parent.Height+1 {
		return "", nil, nil, fmt.Errorf("%s rejected: unknown parent or wrong height", b.ID)
	}
	n.blocks[b.ID] = b
	n.total[b.ID] = n.total[b.Parent] + b.Work
	if n.total[b.ID] <= n.total[n.head] {
		return "", nil, nil, nil
	}
	old := n.head
	n.head = b.ID
	ancestor, undo, apply = n.route(old, b.ID)
	return ancestor, undo, apply, nil
}

// route walks both tips back to their common ancestor.
func (n *Node) route(from, to string) (string, []string, []string) {
	a, b := n.blocks[from], n.blocks[to]
	var undo, apply []string
	for a.Height > b.Height {
		undo, a = append(undo, a.ID), n.blocks[a.Parent]
	}
	for b.Height > a.Height {
		apply, b = append(apply, b.ID), n.blocks[b.Parent]
	}
	for a.ID != b.ID {
		undo, a = append(undo, a.ID), n.blocks[a.Parent]
		apply, b = append(apply, b.ID), n.blocks[b.Parent]
	}
	slices.Reverse(apply)
	return a.ID, undo, apply
}

// Indexer keeps a projection that can be rolled back block by block.
type Indexer struct {
	node     *Node
	included map[string]string // deposit -> canonical block containing it
}

func (ix *Indexer) Apply(id string) {
	for _, d := range ix.node.blocks[id].Deposits {
		ix.included[d] = id
	}
}

func (ix *Indexer) Undo(id string) {
	for _, d := range ix.node.blocks[id].Deposits {
		delete(ix.included, d)
	}
}

func (ix *Indexer) Add(b Block) {
	ancestor, undo, apply, err := ix.node.Add(b)
	if err != nil {
		fmt.Println(err)
		return
	}
	if len(undo) > 0 {
		fmt.Printf("%s arrives: reorg via %s, undo %v, apply %v\n", b.ID, ancestor, undo, apply)
	}
	for _, id := range undo {
		ix.Undo(id) // newest first: the reverse of how they were applied
	}
	for _, id := range apply {
		ix.Apply(id)
	}
}

func (ix *Indexer) Status(dep string, need uint64) {
	head := ix.node.blocks[ix.node.head]
	id, ok := ix.included[dep]
	if !ok {
		fmt.Printf("%s: not on the canonical chain (head %s)\n", dep, head.ID)
		return
	}
	conf := head.Height - ix.node.blocks[id].Height + 1
	fmt.Printf("%s: in %s, confirmations %d, credit at %d: %v\n", dep, id, conf, need, conf >= need)
}

func main() {
	ix := &Indexer{node: NewNode(Block{ID: "G"}), included: map[string]string{}}
	for _, b := range []Block{
		{ID: "A1", Parent: "G", Height: 1, Work: 1},
		{ID: "A2", Parent: "A1", Height: 2, Work: 1},
		{ID: "A3", Parent: "A2", Height: 3, Work: 1, Deposits: []string{"dep-7"}},
		{ID: "A4", Parent: "A3", Height: 4, Work: 1},
	} {
		ix.Add(b)
	}
	fmt.Println("head", ix.node.head, "work", ix.node.total[ix.node.head])
	ix.Status("dep-7", 3)

	ix.Add(Block{ID: "B2", Parent: "A1", Height: 2, Work: 2})
	fmt.Println("after B2 head", ix.node.head, "(B2 total work", ix.node.total["B2"], "is not more)")
	ix.Add(Block{ID: "B3", Parent: "B2", Height: 3, Work: 2})
	fmt.Println("head", ix.node.head, "height 3 work", ix.node.total["B3"], "beats A4 height 4 work", ix.node.total["A4"])
	ix.Status("dep-7", 3)

	ix.Add(Block{ID: "X9", Parent: "unknown", Height: 9, Work: 100})

	ix.Add(Block{ID: "B4", Parent: "B3", Height: 4, Work: 2, Deposits: []string{"dep-7"}})
	ix.Status("dep-7", 3)
}

