import (
	"errors"
	"fmt"
	"math/big"
	"strings"

	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/core/types"
	"github.com/ethereum/go-ethereum/params"
)

// FeePolicy is owned by the signing service, not by the fee oracle.
type FeePolicy struct {
	MaxFeePerGas *big.Int // highest maxFeePerGas the service will sign
	MaxTotalFee  *big.Int // highest gasLimit * maxFeePerGas, in wei
}

var errAbovePolicy = errors.New("refusing to sign")

func gwei(n int64) *big.Int {
	return new(big.Int).Mul(big.NewInt(n), big.NewInt(params.GWei))
}

// formatGwei prints a non-negative wei amount as gwei without floating point.
func formatGwei(wei *big.Int) string {
	q, r := new(big.Int).QuoRem(wei, big.NewInt(params.GWei), new(big.Int))
	if r.Sign() == 0 {
		return q.String() + " gwei"
	}
	frac := strings.TrimRight(fmt.Sprintf("%09d", r.Uint64()), "0")
	return q.String() + "." + frac + " gwei"
}

// feeCapFor leaves room for the base fee to double before inclusion.
func feeCapFor(baseFee, tip *big.Int) *big.Int {
	c := new(big.Int).Mul(baseFee, big.NewInt(2))
	return c.Add(c, tip)
}

// effectivePrice is min(feeCap, baseFee+tipCap). Below baseFee it is not includable.
func effectivePrice(baseFee, tipCap, feeCap *big.Int) (*big.Int, error) {
	if feeCap.Cmp(baseFee) < 0 {
		return nil, errors.New("max fee below base fee")
	}
	p := new(big.Int).Add(baseFee, tipCap)
	if p.Cmp(feeCap) > 0 {
		p.Set(feeCap)
	}
	return p, nil
}

func checkPolicy(p FeePolicy, gas uint64, tipCap, feeCap *big.Int) error {
	if tipCap.Sign() < 0 || feeCap.Sign() <= 0 || tipCap.Cmp(feeCap) > 0 {
		return errors.New("need 0 <= max priority fee <= max fee")
	}
	if feeCap.Cmp(p.MaxFeePerGas) > 0 {
		return fmt.Errorf("%w: max fee %s > limit %s", errAbovePolicy, formatGwei(feeCap), formatGwei(p.MaxFeePerGas))
	}
	worst := new(big.Int).Mul(new(big.Int).SetUint64(gas), feeCap)
	if worst.Cmp(p.MaxTotalFee) > 0 {
		return fmt.Errorf("%w: worst-case fee %s wei > limit %s wei", errAbovePolicy, worst, p.MaxTotalFee)
	}
	return nil
}

func main() {
	policy := FeePolicy{MaxFeePerGas: gwei(100), MaxTotalFee: big.NewInt(3_000_000_000_000_000)}
	const gasLimit = 21_000
	baseFee, tip := gwei(30), gwei(2) // observed from the latest header and a tip oracle
	feeCap := feeCapFor(baseFee, tip)
	fmt.Println("max priority fee", formatGwei(tip)+", max fee", formatGwei(feeCap))

	fmt.Println(checkPolicy(policy, gasLimit, tip, feeCapFor(gwei(120), tip)))
	fmt.Println(checkPolicy(policy, 200_000, tip, feeCap))
	if err := checkPolicy(policy, gasLimit, tip, feeCap); err != nil {
		panic(err)
	}

	to := common.HexToAddress("0x00000000000000000000000000000000000000aa")
	tx := types.NewTx(&types.DynamicFeeTx{
		ChainID:   big.NewInt(1337),
		Nonce:     0,
		GasTipCap: tip,
		GasFeeCap: feeCap,
		Gas:       gasLimit,
		To:        &to,
		Value:     big.NewInt(10_000_000_000_000_000), // 0.01 ether in wei
	})
	fmt.Println("built unsigned type", tx.Type(), "tx for chain", tx.ChainId())

	for _, b := range []*big.Int{gwei(30), big.NewInt(61_500_000_000), gwei(63)} {
		price, err := effectivePrice(b, tip, feeCap)
		gethTip, gethErr := tx.EffectiveGasTip(b)
		if err != nil {
			fmt.Printf("base %s: not includable (%v)\n", formatGwei(b), gethErr)
			continue
		}
		ourTip := new(big.Int).Sub(price, b)
		fmt.Printf("base %s: pays %s, producer tip %s, geth agrees: %t\n",
			formatGwei(b), formatGwei(price), formatGwei(ourTip), ourTip.Cmp(gethTip) == 0)
	}
	fmt.Println("upfront balance check:", tx.Cost(), "wei")
}

