)

const transferABI = `[{"type":"event","name":"Transfer","anonymous":false,"inputs":[
{"name":"from","type":"address","indexed":true},
{"name":"to","type":"address","indexed":true},
{"name":"value","type":"uint256","indexed":false}]}]`

type Transfer struct {
	From  common.Address
	To    common.Address
	Value *big.Int
}

func decodeTransfer(token abi.ABI, want common.Address, lg *types.Log) (Transfer, error) {
	ev := token.Events["Transfer"]
	if lg.Address != want {
		return Transfer{}, fmt.Errorf("emitted by %s, not the token", lg.Address.Hex())
	}
	if len(lg.Topics) != 3 || lg.Topics[0] != ev.ID {
		return Transfer{}, fmt.Errorf("%d topics, not an ERC-20 Transfer", len(lg.Topics))
	}
	var out Transfer
	if err := token.UnpackIntoInterface(&out, "Transfer", lg.Data); err != nil {
		return Transfer{}, err // fills Value from the data section
	}
	var indexed abi.Arguments
	for _, arg := range ev.Inputs {
		if arg.Indexed {
			indexed = append(indexed, arg)
		}
	}
	if err := abi.ParseTopics(&out, indexed, lg.Topics[1:]); err != nil {
		return Transfer{}, err // fills From and To from topics 1 and 2
	}
	return out, nil
}

// deposits credits each delivered log once, keyed by block hash and log index,
// and reverses the credit when the same log comes back with Removed set.
type deposits struct {
	token    abi.ABI
	contract common.Address
	applied  map[string]bool
	balance  map[common.Address]*big.Int
}

func (d *deposits) onLog(lg *types.Log) {
	t, err := decodeTransfer(d.token, d.contract, lg)
	if err != nil {
		fmt.Printf("log %d skipped: %v\n", lg.Index, err)
		return
	}
	key := fmt.Sprintf("%s/%d", lg.BlockHash.Hex(), lg.Index)
	if d.balance[t.To] == nil {
		d.balance[t.To] = new(big.Int)
	}
	switch {
	case lg.Removed && d.applied[key]:
		d.balance[t.To].Sub(d.balance[t.To], t.Value)
		delete(d.applied, key)
		fmt.Printf("log %d removed: reverse %s\n", lg.Index, t.Value)
	case !lg.Removed && !d.applied[key]:
		d.balance[t.To].Add(d.balance[t.To], t.Value)
		d.applied[key] = true
		fmt.Printf("log %d: credit %s from %s\n", lg.Index, t.Value, t.From.Hex())
	}
}

func (d *deposits) onReceipt(r *types.Receipt) {
	fee := new(big.Int).Mul(new(big.Int).SetUint64(r.GasUsed), r.EffectiveGasPrice)
	fmt.Printf("status %d, gas used %d, fee %s wei, %d logs\n", r.Status, r.GasUsed, fee, len(r.Logs))
	if r.Status != types.ReceiptStatusSuccessful {
		return // reverted: the fee was paid, but no token moved
	}
	for _, lg := range r.Logs {
		d.onLog(lg)
	}
}

func main() {
	token, err := abi.JSON(strings.NewReader(transferABI))
	if err != nil {
		panic(err)
	}
	ev := token.Events["Transfer"]
	fmt.Println("topic0", ev.ID.Hex())
	fmt.Println("equals keccak256 of the signature:", ev.ID == crypto.Keccak256Hash([]byte(ev.Sig)))

	contract := common.HexToAddress("0x00000000000000000000000000000000000000c0")
	impostor := common.HexToAddress("0x00000000000000000000000000000000000000ee")
	from := common.HexToAddress("0x1a642f0E3c3aF545E7AcBD38b07251B3990914F1")
	to := common.HexToAddress("0x00000000000000000000000000000000000000bb")
	data, err := ev.Inputs.NonIndexed().Pack(big.NewInt(2_500_000))
	if err != nil {
		panic(err)
	}
	fromTopic, toTopic := common.BytesToHash(from.Bytes()), common.BytesToHash(to.Bytes())
	blockA := common.HexToHash("0xa1")
	ok := &types.Receipt{
		Status: types.ReceiptStatusSuccessful, GasUsed: 51_000,
		EffectiveGasPrice: big.NewInt(32_000_000_000), BlockHash: blockA,
		Logs: []*types.Log{
			{Address: contract, Topics: []common.Hash{ev.ID, fromTopic, toTopic}, Data: data, BlockHash: blockA, Index: 4},
			{Address: impostor, Topics: []common.Hash{ev.ID, fromTopic, toTopic}, Data: data, BlockHash: blockA, Index: 5},
			{Address: contract, Topics: []common.Hash{ev.ID, fromTopic, toTopic, common.BigToHash(big.NewInt(9))}, BlockHash: blockA, Index: 6},
		},
	}
	reverted := &types.Receipt{Status: types.ReceiptStatusFailed, GasUsed: 29_000, EffectiveGasPrice: big.NewInt(32_000_000_000)}

	d := &deposits{token: token, contract: contract, applied: map[string]bool{}, balance: map[common.Address]*big.Int{}}
	d.onReceipt(ok)
	d.onLog(ok.Logs[0]) // a duplicate delivery changes nothing
	d.onReceipt(reverted)
	fmt.Printf("credited to %s: %s\n", to.Hex(), d.balance[to])

	// Reorg: block A leaves the canonical chain, the log is re-sent with Removed
	// set, and the transaction is included again in block B at another index.
	gone := *ok.Logs[0]
	gone.Removed = true
	d.onLog(&gone)
	again := *ok.Logs[0]
	again.BlockHash, again.Index = common.HexToHash("0xb1"), 0
	d.onLog(&again)
	fmt.Printf("credited after reorg: %s\n", d.balance[to])
}

