package main

import (
	"bytes"
	"errors"
	"fmt"
	"math/big"
	"strings"
	"sync"
	"time"

	"github.com/ethereum/go-ethereum/accounts"
	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/crypto"
)

const header = " wants you to sign in with your Ethereum account:"

var fields = map[string]bool{"URI": true, "Version": true, "Chain ID": true,
	"Nonce": true, "Issued At": true, "Expiration Time": true}

// recoverPersonal returns the address that produced an EIP-191 personal_sign signature.
func recoverPersonal(message string, sig []byte) (common.Address, error) {
	if len(sig) != crypto.SignatureLength {
		return common.Address{}, errors.New("signature must be 65 bytes")
	}
	s := bytes.Clone(sig) // never mutate the caller's slice
	if s[64] == 27 || s[64] == 28 {
		s[64] -= 27 // wallets send 27/28; go-ethereum expects 0/1
	}
	r, sv := new(big.Int).SetBytes(s[:32]), new(big.Int).SetBytes(s[32:64])
	if !crypto.ValidateSignatureValues(s[64], r, sv, true) {
		return common.Address{}, errors.New("invalid or high-s signature")
	}
	pub, err := crypto.SigToPub(accounts.TextHash([]byte(message)), s)
	if err != nil {
		return common.Address{}, err
	}
	return crypto.PubkeyToAddress(*pub), nil
}

// parse reads the EIP-4361 fields this server checks. A production parser
// should implement the full ABNF, including field order and Resources.
func parse(msg string) (map[string]string, error) {
	lines := strings.Split(msg, "\n")
	if len(lines) < 8 || !strings.HasSuffix(lines[0], header) {
		return nil, errors.New("not a sign-in message")
	}
	f := map[string]string{"Domain": strings.TrimSuffix(lines[0], header), "Address": lines[1]}
	for _, line := range lines[2:] {
		k, v, ok := strings.Cut(line, ": ")
		if !ok || !fields[k] {
			continue // blank lines and the free-text statement
		}
		if _, dup := f[k]; dup {
			return nil, fmt.Errorf("duplicate field %q", k)
		}
		f[k] = v
	}
	return f, nil
}

type Server struct {
	Domain, ChainID string
	mu              sync.Mutex
	nonces          map[string]bool // issued and not yet used
}

func (s *Server) Verify(msg string, sig []byte, now time.Time) (common.Address, error) {
	f, err := parse(msg)
	if err != nil {
		return common.Address{}, err
	}
	if f["Domain"] != s.Domain {
		return common.Address{}, fmt.Errorf("domain %q is not %q", f["Domain"], s.Domain)
	}
	if f["URI"] != "https://"+s.Domain+"/login" || f["Version"] != "1" || f["Chain ID"] != s.ChainID {
		return common.Address{}, errors.New("wrong URI, version or chain")
	}
	exp, err := time.Parse(time.RFC3339, f["Expiration Time"])
	if err != nil || !now.Before(exp) {
		return common.Address{}, errors.New("missing or past expiration time")
	}
	claimed := f["Address"]
	if !common.IsHexAddress(claimed) || common.HexToAddress(claimed).Hex() != claimed {
		return common.Address{}, errors.New("address is not EIP-55 checksummed")
	}
	signer, err := recoverPersonal(msg, sig)
	if err != nil {
		return common.Address{}, err
	}
	if signer != common.HexToAddress(claimed) {
		return common.Address{}, fmt.Errorf("signature recovers %s", signer.Hex())
	}
	s.mu.Lock() // consuming the nonce is the commit point
	defer s.mu.Unlock()
	if !s.nonces[f["Nonce"]] {
		return common.Address{}, errors.New("nonce unknown or already used")
	}
	delete(s.nonces, f["Nonce"])
	return signer, nil
}

func message(domain string, addr common.Address, nonce string, issued time.Time) string {
	return domain + header + "\n" + addr.Hex() + "\n\n" +
		"Sign in to the dashboard.\n\n" +
		"URI: https://" + domain + "/login\nVersion: 1\nChain ID: 1337\n" +
		"Nonce: " + nonce + "\n" +
		"Issued At: " + issued.Format(time.RFC3339) + "\n" +
		"Expiration Time: " + issued.Add(5*time.Minute).Format(time.RFC3339)
}

// walletSign mimics personal_sign: EIP-191 hash, then V shifted to 27/28.
func walletSign(msg string, key []byte) []byte {
	prv, err := crypto.ToECDSA(key)
	if err != nil {
		panic(err)
	}
	sig, err := crypto.Sign(accounts.TextHash([]byte(msg)), prv)
	if err != nil {
		panic(err)
	}
	sig[64] += 27
	return sig
}

