// Reader is the slice of *ethclient.Client this service depends on.
type Reader interface {
	HeaderByNumber(ctx context.Context, number *big.Int) (*types.Header, error)
	BalanceAtHash(ctx context.Context, account common.Address, block common.Hash) (*big.Int, error)
}

var _ Reader = (*ethclient.Client)(nil) // the real client fits the same interface

type Provider struct {
	Name string
	Reader
}

// fake is an in-memory node: a header per height, a balance per block hash and a
// script of failures returned before any balance read succeeds.
type fake struct {
	headers  map[uint64]*types.Header
	balances map[common.Hash]*big.Int
	failures []error
}

func (f *fake) HeaderByNumber(ctx context.Context, n *big.Int) (*types.Header, error) {
	if h, ok := f.headers[n.Uint64()]; ok {
		return h, nil
	}
	return nil, ethereum.NotFound // what ethclient returns for a null block
}

func (f *fake) BalanceAtHash(ctx context.Context, _ common.Address, block common.Hash) (*big.Int, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if len(f.failures) > 0 {
		err := f.failures[0]
		f.failures = f.failures[1:]
		return nil, err
	}
	if b, ok := f.balances[block]; ok {
		return new(big.Int).Set(b), nil
	}
	return nil, errors.New("header for hash not found")
}

// pin asks every provider for the header at n and accepts a hash only if a strict
// majority of all configured providers return it.
func pin(ctx context.Context, ps []Provider, n uint64) (common.Hash, []Provider, error) {
	answers := make([]common.Hash, len(ps))
	votes := map[common.Hash]int{}
	var best common.Hash
	for i, p := range ps {
		h, err := p.HeaderByNumber(ctx, new(big.Int).SetUint64(n))
		if err != nil {
			fmt.Printf("%s: no header %d (%v), excluded\n", p.Name, n, err)
			continue
		}
		answers[i] = h.Hash() // computed locally from the returned header fields
		votes[answers[i]]++
		if votes[answers[i]] > votes[best] {
			best = answers[i]
		}
	}
	if 2*votes[best] <= len(ps) {
		return common.Hash{}, nil, fmt.Errorf("no majority for block %d", n)
	}
	var agreeing []Provider
	for i, p := range ps {
		switch answers[i] {
		case best:
			agreeing = append(agreeing, p)
		case common.Hash{}:
		default:
			fmt.Printf("%s: reports %s at %d, quarantined\n", p.Name, answers[i].TerminalString(), n)
		}
	}
	return best, agreeing, nil
}

func retryable(err error) bool {
	var httpErr rpc.HTTPError
	if errors.As(err, &httpErr) {
		return httpErr.StatusCode == http.StatusTooManyRequests || httpErr.StatusCode >= 500
	}
	return errors.Is(err, context.DeadlineExceeded)
}

type Backoff struct {
	Attempts   int
	Base, Max  time.Duration
	Sleep      func(context.Context, time.Duration) error
	PerAttempt time.Duration
}

// balance tries each agreeing provider in order with bounded, growing waits.
func balance(ctx context.Context, ps []Provider, b Backoff, a common.Address, block common.Hash) (*big.Int, error) {
	for _, p := range ps {
		wait := b.Base
		for attempt := 1; attempt <= b.Attempts; attempt++ {
			callCtx, cancel := context.WithTimeout(ctx, b.PerAttempt)
			v, err := p.BalanceAtHash(callCtx, a, block)
			cancel()
			if err == nil {
				fmt.Printf("%s: balance at %s = %s wei\n", p.Name, block.TerminalString(), v)
				return v, nil
			}
			if !retryable(err) || attempt == b.Attempts {
				fmt.Printf("%s: attempt %d: %v, next provider\n", p.Name, attempt, err)
				break
			}
			fmt.Printf("%s: attempt %d: %v, retry in %v\n", p.Name, attempt, err, wait)
			if err := b.Sleep(ctx, wait); err != nil {
				return nil, err
			}
			wait = min(2*wait, b.Max)
		}
	}
	return nil, errors.New("all providers failed")
}

func main() {
	header := func(n uint64, root byte) *types.Header {
		return &types.Header{Number: new(big.Int).SetUint64(n), Difficulty: new(big.Int), Root: common.Hash{root}}
	}
	canonical, fork := header(100, 0xaa), header(100, 0xbb)
	limited := rpc.HTTPError{StatusCode: 429, Status: "429 Too Many Requests"}
	funds := map[common.Hash]*big.Int{canonical.Hash(): big.NewInt(5_000_000_000_000_000_000)}

	providers := []Provider{
		{"alpha", &fake{headers: map[uint64]*types.Header{100: canonical}, balances: funds,
			failures: []error{limited, limited, limited}}},
		{"beta", &fake{headers: map[uint64]*types.Header{100: canonical}, balances: funds}},
		{"gamma", &fake{headers: map[uint64]*types.Header{100: canonical}, balances: funds}},
		{"delta", &fake{headers: map[uint64]*types.Header{100: fork}}},
		{"epsilon", &fake{headers: map[uint64]*types.Header{99: header(99, 0xaa)}}},
	}
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	hash, agreeing, err := pin(ctx, providers, 100)
	if err != nil {
		panic(err)
	}
	fmt.Printf("pinned block 100 = %s, agreed by %d of %d\n", hash.TerminalString(), len(agreeing), len(providers))

	var slept time.Duration
	policy := Backoff{Attempts: 3, Base: 100 * time.Millisecond, Max: time.Second, PerAttempt: 500 * time.Millisecond,
		Sleep: func(_ context.Context, d time.Duration) error { slept += d; return nil }}
	if _, err := balance(ctx, agreeing, policy, common.HexToAddress("0xbb"), hash); err != nil {
		panic(err)
	}
	fmt.Println("total backoff:", slept)
}

type limited struct {
	Reader
	lim *rate.Limiter
}

func (l limited) BalanceAtHash(ctx context.Context, a common.Address, h common.Hash) (*big.Int, error) {
	if err := l.lim.Wait(ctx); err != nil { // errors out if the wait would pass the deadline
		return nil, err
	}
	return l.Reader.BalanceAtHash(ctx, a, h)
}

func dial(ctx context.Context, name, url string, want *big.Int) (Provider, error) {
	rc, err := rpc.DialOptions(ctx, url, rpc.WithHTTPClient(&http.Client{Timeout: 10 * time.Second}))
	if err != nil {
		return Provider{}, err
	}
	client := ethclient.NewClient(rc)
	id, err := client.ChainID(ctx)
	if err != nil || id.Cmp(want) != 0 {
		client.Close()
		return Provider{}, fmt.Errorf("%s: chain %v, want %v (err %v)", name, id, want, err)
	}
	return Provider{Name: name, Reader: limited{client, rate.NewLimiter(20, 5)}}, nil
}

